params.query:
SELECT ?item (SAMPLE(?asi) AS ?asi_id) (SAMPLE(?distLabel) AS ?district) WHERE {
  { ?item wdt:P1371 ?asi . } UNION { ?item wdt:P1435 ?designation . }
  ?item wdt:P131* wd:Q1445 .
  OPTIONAL {
    ?item wdt:P131* ?dist . ?dist wdt:P31 wd:Q1149652 .
    ?dist rdfs:label ?distLabel . FILTER(LANG(?distLabel) = "en")
  }
} GROUP BY ?item
